AHB.audio({"groups": {"part-01-vocabulary": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-01-vocabulary/001.mp3", "text": "We load the cement into a (1)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-01-vocabulary/002.mp3", "text": "A truck takes it to the (2)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-01-vocabulary/003.mp3", "text": "The goods stop at (3)… at the (4)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-01-vocabulary/004.mp3", "text": "We send it by (5)…, with a (6)"}], "title": "Read and listen"}], "part-02-grammar": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-02-grammar/001.mp3", "text": "PREPOSITIONS OF PLACE show where: to (We ship to your country), from (It comes from Syria), in (The goods are in the port), at (It arrives at the port)."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-02-grammar/002.mp3", "text": "PREPOSITIONS OF TIME show when: on + day (on Monday), in + month (in June), at + time (at 9 o'clock)."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-02-grammar/003.mp3", "text": "We use the PRESENT CONTINUOUS (am/is/are + verb-ing) for a plan or arrangement with a time."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-02-grammar/004.mp3", "text": "We are shipping the goods on Monday."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-02-grammar/005.mp3", "text": "The ship is leaving at 9."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-02-grammar/006.mp3", "text": "This is a fixed plan, not just an idea."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-02-grammar/007.mp3", "text": "We use BE GOING TO + verb for a plan we already have."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-02-grammar/008.mp3", "text": "We are going to send it by sea."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-02-grammar/009.mp3", "text": "I am going to send the packing list."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-02-grammar/010.mp3", "text": "Question: Are you going to ship it today?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-02-grammar/011.mp3", "text": "Negative: We are not going to use a plane."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-02-grammar/012.mp3", "text": "On for days, in for months, at for times: on Monday, in June, at 9."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-02-grammar/013.mp3", "text": "For present continuous, use am/is/are + verb-ing (We are shipping — NOT 'We shipping')."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-02-grammar/014.mp3", "text": "For 'going to', use am/is/are going to + verb (I am going to send — NOT 'I going to send')."}], "title": "Read and listen"}], "part-03-listening": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-03-listening/001.mp3", "text": "Listen and read. (Your teacher will read the dialogue, or play the audio.)"}], "title": "Read and listen"}, {"clips": [{"ar": "مرحباً يا فادي. متى ستشحن طلبي؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-03-listening/002.mp3", "text": "Hello, Fadi. When are you shipping my order?"}, {"ar": "سنشحنه يوم الاثنين، بحراً، من ميناء اللاذقية.", "speaker": "Fadi", "src": "../../assets/audio/unit-06/part-03-listening/003.mp3", "text": "We are shipping it on Monday, by sea, from Latakia port."}, {"ar": "جيد. كيف يسافر؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-03-listening/004.mp3", "text": "Good. How does it travel?"}, {"ar": "أولاً، تأخذ شاحنة الأكياس إلى الميناء. ثم نحمّلها في حاوية.", "speaker": "Fadi", "src": "../../assets/audio/unit-06/part-03-listening/005.mp3", "text": "First, a truck takes the bags to the port. Then we load them into a container."}, {"ar": "والجمارك؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-03-listening/006.mp3", "text": "And customs?"}, {"ar": "تجتاز البضائع الجمارك يوم الأربعاء. بعد ذلك، تُشحن على السفينة.", "speaker": "Fadi", "src": "../../assets/audio/unit-06/part-03-listening/007.mp3", "text": "The goods clear customs on Wednesday. After that, they go on the ship."}, {"ar": "كم يستغرق ذلك؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-03-listening/008.mp3", "text": "How long does it take?"}, {"ar": "نحو أسبوعين. يصل إلى مينائك في الأسبوع الأول من حزيران.", "speaker": "Fadi", "src": "../../assets/audio/unit-06/part-03-listening/009.mp3", "text": "About two weeks. It arrives at your port in the first week of June."}, {"ar": "ممتاز. هل ستُرسل قائمة التعبئة؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-03-listening/010.mp3", "text": "Perfect. Are you going to send the packing list?"}, {"ar": "نعم. سأرسلها بالبريد الإلكتروني اليوم.", "speaker": "Fadi", "src": "../../assets/audio/unit-06/part-03-listening/011.mp3", "text": "Yes. I am going to send it with an email today."}], "title": "Dialogue D1"}, {"clips": [{"ar": "كم يستغرق التسليم؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-03-listening/012.mp3", "text": "How long does delivery take?"}, {"ar": "بحراً، نحو أسبوعين. براً، نحو أسبوع، لكنه يكلّف أكثر.", "speaker": "Fadi", "src": "../../assets/audio/unit-06/part-03-listening/013.mp3", "text": "By sea, about two weeks. By land, about one week, but it costs more."}, {"ar": "لسنا في عجلة. بحراً مناسب.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-03-listening/014.mp3", "text": "We are not in a hurry. By sea is fine."}, {"ar": "جيد. سنشحنه بحراً يوم الاثنين.", "speaker": "Fadi", "src": "../../assets/audio/unit-06/part-03-listening/015.mp3", "text": "Good. We are going to ship it by sea on Monday."}, {"ar": "ومتى يصل؟", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-03-listening/016.mp3", "text": "And when does it arrive?"}, {"ar": "في الأسبوع الأول من حزيران، في مينائك.", "speaker": "Fadi", "src": "../../assets/audio/unit-06/part-03-listening/017.mp3", "text": "In the first week of June, at your port."}, {"ar": "شكراً. هذا ممتاز.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-03-listening/018.mp3", "text": "Thank you. That is perfect."}], "title": "Dialogue D2"}], "part-04-speaking": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-04-speaking/001.mp3", "text": "A: Ask 'When are you shipping my order?'"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-04-speaking/002.mp3", "text": "B: Say the date ('We are shipping it on…')."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-04-speaking/003.mp3", "text": "B: Describe the route (first, then, next…)."}], "title": "Read and listen"}], "part-05-reading": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/001.mp3", "text": "Think about a box of cement."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/002.mp3", "text": "It starts in a factory in Aleppo."}, {"ar": "وينتهي في مبنى بعيد، في بلد آخر.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/003.mp3", "text": "It ends in a building far away, in another country."}, {"ar": "بين هذين المكانين، يقطع رحلة طويلة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/004.mp3", "text": "Between these two places, it makes a long journey."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/005.mp3", "text": "Most people never think about this journey."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/006.mp3", "text": "But it is one of the most important jobs in the world."}, {"ar": "أولاً، يعبّئ العمال الإسمنت في أكياس.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/007.mp3", "text": "First, workers pack the cement into bags."}, {"ar": "ثم يضعون الأكياس في حاوية كبيرة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/008.mp3", "text": "Then they put the bags into a big container."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/009.mp3", "text": "A truck takes the container to the port."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/010.mp3", "text": "This is the first part of the journey — by land."}, {"ar": "في الميناء، ترفع رافعة كبيرة الحاوية إلى السفينة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/011.mp3", "text": "At the port, a big crane lifts the container onto a ship."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/012.mp3", "text": "Then the ship sails across the sea."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/013.mp3", "text": "This is the longest part — by sea."}, {"ar": "قد يستغرق أسبوعين أو أكثر.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/014.mp3", "text": "It can take two weeks or more."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/015.mp3", "text": "But there is one more stop: customs."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/016.mp3", "text": "Every country has a border."}, {"ar": "عند الحدود، يفحص مكتب الجمارك البضائع.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/017.mp3", "text": "At the border, the customs office checks the goods."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/018.mp3", "text": "Are the papers correct?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/019.mp3", "text": "Is this the right cargo?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/020.mp3", "text": "Is there any tax to pay?"}, {"ar": "تنتظر البضائع في الجمارك حتى يصبح كل شيء صحيحاً.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/021.mp3", "text": "The goods wait at customs until everything is right."}, {"ar": "لهذا السبب المستندات مهمة جداً.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/022.mp3", "text": "This is why documents are so important."}, {"ar": "بدون الأوراق الصحيحة، تتوقف البضائع عند الحدود، ولا يستطيع أحد تحريكها.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/023.mp3", "text": "Without the right papers, the goods stop at the border, and nobody can move them."}, {"ar": "عندما تجتاز البضائع الجمارك، يبدأ الجزء الأخير.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/024.mp3", "text": "When the goods clear customs, the last part begins."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/025.mp3", "text": "A truck takes the container from the port to the partner's door."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/026.mp3", "text": "The journey is finished."}, {"ar": "صندوق الإسمنت، المصنوع في سوريا، صار الآن في مبنى في بلد آخر.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/027.mp3", "text": "The box of cement, made in Syria, is now in a building in another country."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/028.mp3", "text": "And most people never see this journey."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/029.mp3", "text": "They only see the building."}, {"ar": "هذه هي القوة الهادئة للخدمات اللوجستية: تحرّك العالم، وتؤدي عملها بلا ضجيج.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/030.mp3", "text": "This is the quiet power of logistics: it moves the world, and it does its work without noise."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/031.mp3", "text": "Every road, every port, every ship, every truck — together, they carry the things we use every day."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/032.mp3", "text": "Logistics is invisible when it works well."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/033.mp3", "text": "But it is the reason the world can trade."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/034.mp3", "text": "A box of cement makes a long (1)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/035.mp3", "text": "A truck takes it to the (2)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/036.mp3", "text": "A ship carries it across the (3)"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/037.mp3", "text": "At the border, (4)… checks the goods and the papers."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/038.mp3", "text": "Then a truck takes it to the partner."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-05-reading/039.mp3", "text": "Logistics is (5)… when it works well, but it moves the (6)"}], "title": "Read and listen"}], "part-06-writing": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-06-writing/001.mp3", "text": "I said when we are shipping (on Monday…)."}], "title": "Read and listen"}], "part-07-trade-skills": [{"clips": [{"ar": "عندما تسافر البضائع بين البلدان، تكون المستندات بأهمية البضائع نفسها.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-07-trade-skills/001.mp3", "text": "When goods travel between countries, the documents are as important as the goods."}, {"ar": "أهم مستند هو قائمة التعبئة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-07-trade-skills/002.mp3", "text": "The most important document is the PACKING LIST."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-07-trade-skills/003.mp3", "text": "It says exactly what is in the container: the product, the quantity, the number of boxes or bags, and the weight."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-07-trade-skills/004.mp3", "text": "Why is this so important?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-07-trade-skills/005.mp3", "text": "Because of customs."}, {"ar": "لكل بلد حدود، ولكل حدود مكتب جمارك.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-07-trade-skills/006.mp3", "text": "Every country has a border, and every border has a customs office."}, {"ar": "عندما تصل البضائع إلى الحدود، يقرأ مكتب الجمارك قائمة التعبئة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-07-trade-skills/007.mp3", "text": "When the goods arrive at the border, the customs office reads the packing list."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-07-trade-skills/008.mp3", "text": "It checks: is this the right cargo?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-07-trade-skills/009.mp3", "text": "Is the quantity correct?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-07-trade-skills/010.mp3", "text": "Is there any tax to pay?"}, {"ar": "إذا كانت الأوراق صحيحة، تجتاز البضائع الجمارك، وتستطيع المتابعة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-07-trade-skills/011.mp3", "text": "If the papers are correct, the goods clear customs, and they can continue."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-07-trade-skills/012.mp3", "text": "If the papers are wrong, or missing, the goods stop."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-07-trade-skills/013.mp3", "text": "They wait at the border."}, {"ar": "وهذا يكلّف وقتاً ومالاً.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-07-trade-skills/014.mp3", "text": "This costs time and money."}, {"ar": "لذلك يجهّز فريق لوجستي جيد المستندات بعناية دائماً، ويرسلها مبكراً دائماً.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-07-trade-skills/015.mp3", "text": "So a good logistics team always prepares the documents carefully, and always sends them early."}, {"ar": "تذكّر: لا تتحرك البضائع أسرع من الأوراق.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-07-trade-skills/016.mp3", "text": "Remember: the goods can only move as fast as the papers."}, {"ar": "المستندات الجيدة تعني تسليماً سريعاً.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-07-trade-skills/017.mp3", "text": "Good documents mean fast delivery."}, {"ar": "المستندات السيئة تعني شحنة عالقة عند الحدود.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-07-trade-skills/018.mp3", "text": "Bad documents mean a shipment stuck at the border."}, {"ar": "في الخدمات اللوجستية، الأوراق ليست مملّة. إنها المفتاح الذي يفتح كل حدود.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-07-trade-skills/019.mp3", "text": "In logistics, the paperwork is not boring — it is the key that opens every border."}], "title": "Read and listen"}], "part-08-consolidation": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/001.mp3", "text": "It is Monday morning."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/002.mp3", "text": "The container of cement is ready."}, {"ar": "تأخذها شاحنة من المصنع في حلب إلى ميناء اللاذقية.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/003.mp3", "text": "A truck takes it from the factory in Aleppo to Latakia port."}, {"ar": "في الميناء، ترفعها رافعة كبيرة إلى السفينة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/004.mp3", "text": "At the port, a big crane lifts it onto the ship."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/005.mp3", "text": "Fadi watches, and he is happy."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/006.mp3", "text": "Everything is on time."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/007.mp3", "text": "But logistics needs care."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/008.mp3", "text": "On Tuesday, Fadi checks the shipment."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/009.mp3", "text": "He sends Ms. Chen a short message: “Good news."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/010.mp3", "text": "Your order is at Latakia port."}, {"ar": "يجتاز الجمارك غداً، ثم يُشحن على السفينة.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/011.mp3", "text": "It clears customs tomorrow, and then it goes on the ship."}, {"ar": "يصل خلال أسبوعين تقريباً.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/012.mp3", "text": "It arrives in about two weeks.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/013.mp3", "text": "Ms. Chen is happy."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/014.mp3", "text": "She knows exactly where her goods are."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/015.mp3", "text": "“This is good service,” she thinks."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/016.mp3", "text": "“They tell me the news."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/017.mp3", "text": "I am not waiting in the dark.”"}, {"ar": "بعد أسبوعين، تصل السفينة إلى ميناء نورث بريدج.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/018.mp3", "text": "Two weeks later, the ship arrives at NorthBridge's port."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/019.mp3", "text": "A truck takes the container to NorthBridge's door."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/020.mp3", "text": "The journey is finished."}, {"ar": "تكتب السيدة تشِن إلى فادي. الإسمنت هنا، وهو ممتاز.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/021.mp3", "text": "Ms. Chen writes to Fadi: “The cement is here, and it is perfect."}, {"ar": "شكراً على الشحن الجيد، وعلى كل التحديثات.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/022.mp3", "text": "Thank you for the good shipping, and for all the updates.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/023.mp3", "text": "Fadi is proud."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/024.mp3", "text": "“We made good cement,” he thinks."}, {"ar": "ونقلناه بأمان، في موعده، عبر البحر.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/025.mp3", "text": "“And we moved it safely, on time, across the sea."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/026.mp3", "text": "Good products and good logistics — together, they make a happy partner."}, {"ar": "والشريك السعيد يعود.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-08-consolidation/027.mp3", "text": "And a happy partner comes back.”"}], "title": "Read and listen"}], "part-09-cases": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-09-cases/001.mp3", "text": "A shipment arrives at the border."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-09-cases/002.mp3", "text": "But there is no packing list."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-09-cases/003.mp3", "text": "The customs office cannot check the goods, so it stops the shipment."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-09-cases/004.mp3", "text": "The goods wait at the border for days."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-09-cases/005.mp3", "text": "Write one sentence to tell the customs office what is in the container."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-09-cases/006.mp3", "text": "A partner needs 5,000 tonnes of cement, but they are not in a hurry."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-09-cases/007.mp3", "text": "By sea is cheaper but slower."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-09-cases/008.mp3", "text": "By land is faster but more expensive."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-09-cases/009.mp3", "text": "You ship a partner's order, but you do not send any updates."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-09-cases/010.mp3", "text": "The partner does not know where the goods are."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-09-cases/011.mp3", "text": "They are worried, and they send many emails to ask."}], "title": "Read and listen"}], "part-10-review": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-10-review/001.mp3", "text": "We are shipping the order by sea on Monday."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-10-review/002.mp3", "text": "First, a truck takes the container to Latakia port."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-10-review/003.mp3", "text": "Then the goods clear customs."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-10-review/004.mp3", "text": "After that, they go on the ship."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-10-review/005.mp3", "text": "It arrives at the partner's port in about two weeks."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-10-review/006.mp3", "text": "We send the packing list with the shipment."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-10-review/007.mp3", "text": "[Teacher reads] 'We are shipping your order on Monday, by sea, from Latakia port."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-10-review/008.mp3", "text": "The goods clear customs on Wednesday."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-10-review/009.mp3", "text": "It arrives at your port in about two weeks.'"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-10-review/010.mp3", "text": "I can describe how goods travel, step by step."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-10-review/011.mp3", "text": "I can use prepositions of place and time."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-10-review/012.mp3", "text": "I can talk about plans and arrangements."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-10-review/013.mp3", "text": "I can write a short shipping-update message."}], "title": "Read and listen"}], "part-11-foundations": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/001.mp3", "text": "This unit is about shipping."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/002.mp3", "text": "But it points to a big idea: the world is full of systems you never see."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/003.mp3", "text": "Logistics is one of them."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/004.mp3", "text": "Every day, ships, trucks, and planes move millions of boxes around the world."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/005.mp3", "text": "You do not see this."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/006.mp3", "text": "But it is the reason your shop has food, your city has fuel, and your building has cement."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/007.mp3", "text": "When the system works, it is invisible."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/008.mp3", "text": "You only notice it when it stops."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/009.mp3", "text": "Think about it."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/010.mp3", "text": "When you buy something, you see the shop and the box."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/011.mp3", "text": "You do not see the long journey — the factory, the truck, the port, the ship, the customs office."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/012.mp3", "text": "All of this happens quietly, behind the scenes."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/013.mp3", "text": "Thousands of people do this work every day, and most of us never think about them."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/014.mp3", "text": "But without them, the world stops."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/015.mp3", "text": "No cement for buildings."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/016.mp3", "text": "No food for shops."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/017.mp3", "text": "No fuel for cars."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/018.mp3", "text": "The invisible system holds up the visible world."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/019.mp3", "text": "This is true of many systems, not just logistics."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/020.mp3", "text": "Think of the water in your tap, the power in your lights, the roads under your car."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/021.mp3", "text": "You do not see these systems."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/022.mp3", "text": "You only use them."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/023.mp3", "text": "And this teaches us something important."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/024.mp3", "text": "The most valuable work is often the quiet work that nobody sees."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/025.mp3", "text": "The person who packs the box, checks the papers, and loads the ship is not famous."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/026.mp3", "text": "But their careful work moves the world."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/027.mp3", "text": "So as you work in trade, remember two things."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/028.mp3", "text": "First, respect the invisible systems, and the people who keep them working."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/029.mp3", "text": "They do a great and quiet job."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/030.mp3", "text": "Second, do quiet, careful work yourself: a good packing list, a clear update, an on-time shipment."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/031.mp3", "text": "Then you are part of this great system."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/032.mp3", "text": "Your work can be invisible."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/033.mp3", "text": "But it matters."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/034.mp3", "text": "It helps goods move, partners trust, and the world trade."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/035.mp3", "text": "And that is something to be proud of, even when nobody sees it."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/036.mp3", "text": "Choose one thing near you (food, a phone, cement)."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/037.mp3", "text": "Think about its long journey to you: the factory, the transport, the shop."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/038.mp3", "text": "How many people helped it travel?"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/039.mp3", "text": "Write a few sentences (30–50 words) about how goods travel from your country to a partner."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/part-11-foundations/040.mp3", "text": "Use 'first, then, next, finally' and prepositions of place and time."}], "title": "Read and listen"}], "warm-up": [{"clips": [{"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/001.mp3", "text": "Look at the pictures."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/002.mp3", "text": "Answer these questions before you read."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/003.mp3", "text": "NorthBridge's order is ready."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/004.mp3", "text": "Now the goods travel to NorthBridge's country."}, {"ar": "هذا هو عمل الخدمات اللوجستية: نقل البضائع من مكان إلى آخر.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/005.mp3", "text": "This is the job of logistics — moving goods from one place to another."}, {"ar": "في الحسن، تقوم شركة الشحن كوموش بهذا العمل.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/006.mp3", "text": "At Al-Hasan, the freight company Komosh does this work."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/007.mp3", "text": "Karim talks to Fadi."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/008.mp3", "text": "“The cement is ready in Aleppo,” he says."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/009.mp3", "text": "“How do we send it to NorthBridge?”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/010.mp3", "text": "Fadi checks the plan."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/011.mp3", "text": "“We are shipping it by sea,” he says."}, {"ar": "أولاً، تأخذ شاحنة الأكياس من المصنع في حلب إلى ميناء اللاذقية.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/012.mp3", "text": "“First, a truck takes the bags from the factory in Aleppo to Latakia port."}, {"ar": "ثم نحمّل الحاوية.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/013.mp3", "text": "Then we load the container."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/014.mp3", "text": "Next, the goods clear customs."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/015.mp3", "text": "After that, they go on the ship."}, {"ar": "أخيراً، تبحر السفينة إلى ميناء نورث بريدج.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/016.mp3", "text": "Finally, the ship sails to NorthBridge's port.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/017.mp3", "text": "“How long does it take?” asks Karim."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/018.mp3", "text": "“About two weeks by sea,” says Fadi."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/019.mp3", "text": "“By land, it is faster, but the roads are long."}, {"ar": "بحراً. فهو أرخص للطلب الكبير.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/020.mp3", "text": "By sea, it is cheaper for a big order.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/021.mp3", "text": "Fadi prepares the documents."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/022.mp3", "text": "The most important one is the packing list."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/023.mp3", "text": "It says what is in the container: 1,000 tonnes of cement, in 20,000 bags, in two containers."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/024.mp3", "text": "The customs office needs this document."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/025.mp3", "text": "Without the right papers, the goods cannot cross the border."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/026.mp3", "text": "“When are we shipping it?” asks Karim."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/027.mp3", "text": "“We are shipping it on Monday,” says Fadi."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/028.mp3", "text": "“The ship leaves Latakia at 9 in the morning."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/029.mp3", "text": "It arrives at NorthBridge's port in about two weeks."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/030.mp3", "text": "I am going to send Ms. Chen an update, with the date and the packing list.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/031.mp3", "text": "Fadi writes to Ms. Chen: “Dear Ms. Chen, good news."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/032.mp3", "text": "We are shipping your order by sea on Monday."}, {"ar": "يصل خلال أسبوعين تقريباً.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/033.mp3", "text": "It arrives in about two weeks."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/034.mp3", "text": "Best, Fadi.”"}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/035.mp3", "text": "“Good work,” says Karim."}, {"ar": "", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/036.mp3", "text": "“Now the goods are on their way."}, {"ar": "هذه هي الخدمات اللوجستية: العمل الهادئ الذي يحرّك العالم.", "speaker": "Ms. Chen", "src": "../../assets/audio/unit-06/warm-up/037.mp3", "text": "This is logistics: the quiet work that moves the world.”"}], "title": "Read and listen"}]}, "unit": 6});
